// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter reverter;
    function setUp() public {
        c = new C();
        reverter = new Reverter();
    }
    function testFuzz_property(address caller, uint256 amount) public {
        // Keep inputs admissible: non-zero caller, reasonable amount (>0)
        vm.assume(caller != address(0));
        vm.assume(amount > 0);
        // Fund the caller and make two deposits via addToBalance
        vm.deal(caller, amount * 2);
        vm.startPrank(caller);
        c.addToBalance{value: amount}();
        c.addToBalance{value: amount}();
        // Now try to withdraw: c sends funds to the Reverter, which always reverts
        // The reference C should leave the balance unchanged on failed withdrawal;
        // the buggy mutant zeroes the balance before the require on each addToBalance,
        // but the require passes because the sent amount >= 0, so the balance becomes amount on each call,
        // overwriting the previous balance. After two calls, the balance is amount (not 2*amount),
        // and a failed withdrawal still sets it to 0, losing the funds.
        // Actually, the difference is: in the buggy version, addToBalance resets balance to 0 BEFORE the require,
        // so the final balance is just the last msg.value, not the sum. After two calls of 'amount',
        // reference balance = 2*amount, buggy balance = amount.
        // The failed withdraw in reference keeps balance = 2*amount; in buggy it sets balance to 0 and fails,
        // leaving balance = 0.
        bool ok;
        try c.withdrawBalance() { ok = true; } catch { ok = false; }
        // Withdrawal should fail (Reverter fallback reverts).
        // In both versions, the call reverts, but the state change differs:
        // Reference: userBalance[caller] remains 2*amount (because transfer fails after balance=0 assignment? Wait, in withdrawBalance, balance is set to 0 BEFORE the call. So reference also sets to 0 and then reverts? Let's check reference withdrawBalance:
        // uint256 tmp__1 = userBalance[msg.sender];
        // userBalance[msg.sender] = 0;
        // (bool _s, bytes memory _d) = msg.sender.call{value: tmp__1}(""); if (!_s) { revert(); }
        // If call fails, it reverts. But the state change userBalance[msg.sender] = 0 happened BEFORE the call, and since the whole transaction reverts, that change is also reverted. So in reference, balance stays 2*amount.
        // In mutant, addToBalance zeroes balance at the start: userBalance[msg.sender] = 0; require(...); balance += msg.value;
        // So each addToBalance overwrites the balance to msg.value, not accumulating. After two calls, balance = amount.
        // Failed withdraw in mutant: sets to 0, then call fails, reverts, so balance reverts to amount (the pre-withdraw state).
        // So reference final balance = 2*amount, mutant final balance = amount.
        // We can assert final balance equals 2*amount (reference will pass, mutant will fail).
        assertEq(c.getBalance(caller), amount * 2);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

