pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, address other, uint256 amount) public {
        vm.assume(sender != address(c));
        vm.assume(other != address(c));
        vm.assume(sender != other);
        vm.assume(amount > 0);

        // fund sender and add to balance
        vm.deal(sender, amount);
        vm.prank(sender);
        c.addToBalance{value: amount}();

        // record the contract ETH balance after the deposit
        uint256 contractBalanceAfter = address(c).balance;

        // have another user withdraw their own (zero) balance; this call succeeds but removes 0 ETH
        vm.prank(other);
        c.withdrawBalance();

        // after an unrelated withdrawal, the contract should still hold at least the previously recorded ETH,
        // because the other user had zero balance to withdraw. The buggy version resets the sender's balance to 0
        // before adding, so the sender's balance is recorded as amount instead of amount+previous_balance, and
        // later the sender can withdraw amount while the contract's ETH may be insufficient for all recorded balances.
        // This immediate check ensures the contract still has all ETH from the deposit.
        assertTrue(address(c).balance == contractBalanceAfter);
    }
}

