pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address caller, uint256 otherAmount, address other) public {
        // Ensure callers are distinct and non-zero address to avoid interference
        vm.assume(caller != address(0));
        vm.assume(other != address(0));
        vm.assume(caller != other);
        // Restrict amounts to avoid overflow in reference contract (realistic domain)
        vm.assume(amount <= type(uint256).max / 2);
        vm.assume(otherAmount <= type(uint256).max / 2);

        // Record initial balances
        uint256 initialBalanceCaller = c.getBalance(caller);
        uint256 initialBalanceOther = c.getBalance(other);

        // Fund callers
        vm.deal(caller, amount);
        vm.deal(other, otherAmount);

        // Caller deposits
        vm.prank(caller);
        c.addToBalance{value: amount}();

        // Other deposits
        vm.prank(other);
        c.addToBalance{value: otherAmount}();

        // Final balances
        uint256 finalBalanceCaller = c.getBalance(caller);
        uint256 finalBalanceOther = c.getBalance(other);

        // General rule: for any user, the increase in balance equals the amount they deposited.
        // Reference C satisfies this; mutant breaks it by checking overflow against userBalance[address(0)]
        // while crediting msg.sender, so a caller can inflate its balance without depositing corresponding ether.
        // Specifically, if address(0) has zero balance, the overflow check passes for any amount,
        // but msg.sender gets credited without depositing? Wait, the call still requires msg.value.
        // The bug: require checks userBalance[address(0)]+msg.value >= userBalance[address(0)], which is always true if address(0) balance is 0 (or any value), so overflow check does not protect msg.sender.
        // Then userBalance[msg.sender] += msg.value, so caller ALWAYS gets credited the amount they send.
        // The reference also credits the amount they send. So where is the difference?
        // The difference is that in the reference, overflow check is on userBalance[msg.sender], so if a caller's balance is very large, adding might overflow and revert. In the mutant, the overflow check is on address(0), so a caller with a balance near max can still add without overflow, allowing them to overflow their own balance during addition.
