        // Therefore: userBalance after call should be >= userBalance before call + msg.value (unless overflow, which reverts). The mutant can produce final balance < initial balance + amount due to overflow, breaking monotonic increase.

        // Assert: final balance >= initial balance + amount deposited (since reference reverts on overflow, this holds; mutant may wrap)
        assertTrue(finalBalanceCaller >= initialBalanceCaller + amount);
        assertTrue(finalBalanceOther >= initialBalanceOther + otherAmount);
    }
}

