pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(actor, amount);
        uint256 beforeSum = getTotalUserBalance();
        vm.prank(actor);
        c.addToBalance{value: amount}();
        uint256 afterSum = getTotalUserBalance();
        assertTrue(address(c).balance == afterSum);
    }

    function getTotalUserBalance() internal view returns (uint256 sum) {
        // Since mapping is private we need to iterate through all possible addresses.
        // In Foundry fuzzing, we observe the effect: we know that only `actor` has a balance change.
        // A correct approach is to use the public `getBalance` to check the actor's balance.
        // But the rule must hold for any actor, not just the caller.
        // The contract's total balance must match the sum of all individual user balances.
        // Since userBalance mapping is inaccessible except through getBalance,
        // we can compute the sum by querying getBalance for the actor and for a second address that might have balance.
        // In the general case this is impossible to iterate all addresses.
        // Therefore we need a different approach: use the fact that the invariant is
        // address(c).balance == sum over all users.
        // After a single addToBalance, the sum must increase exactly by amount.
        // The simplest enforceable invariant: after addToBalance, the contract balance must be at least the user's new balance.
        // But the mutation allows overflow, where userBalance can wrap around but contract balance still increases.
        // So the contract balance will be larger than the sum of all balances.
        // To check the total sum, we need to know the previous sum. In a fuzz test, we can store a running total.
        // This requires a state variable in the test contract to track the expected sum.
        // However the instructions say "end with exactly one assertion the reference satisfies for ALL admissible inputs".
        // A cleaner way: the correct contract ensures that for any user, userBalance <= address(c).balance.
        // In the buggy version, an overflow can cause userBalance to be very small, so this might hold.
        // The requirement is that the total contract balance equals the sum of all balances.
        // We can track the sum in the test contract.
        sum = c.getBalance(actor); // not sufficient alone, but we can store mapping externally.
        // Actually, we can use a helper: the test contract maintains a public mapping(address => uint256) expectedBalance.
        // But that is not allowed to assert on helper.
        // Alternative: use two calls and compare the increment.
        // The property: after addToBalance, the user's balance increases by exactly amount.
        // This holds in reference, fails in bug because overflow can make the balance smaller.
        uint256 balBefore = c.getBalance(actor);
        uint256 balAfter = c.getBalance(actor);
        assertTrue(balAfter == balBefore + amount);
        // This assertion checks that the user's balance is updated correctly.
        // In the buggy version, overflow happens when balBefore + amount > 2^256-1, then balAfter != balBefore + amount.
        // This satisfies "the value of state variable addToBalance differs" note? They said "addToBalance() != M.addToBalance()" which is vague.
        // The simpler correct test: after addToBalance, contract balance == sum of all user balances.
        // Since we cannot iterate all addresses, we can use the fact that the fuzzer will try different actors.
        // We can instead assert that contract balance >= sum of balances of all actors ever called? Not possible without storage.
        // Let's use the simplest correct property: the user's balance after the call must be exactly balBefore + amount (no overflow).
        // This is exactly what the require was checking.
        // The bug removes that check, so overflow is possible.
        // The fuzz test will find values where overflow occurs and the assertion fails.
        // This is a valid property and uses only public getBalance.
    }
}

