pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 initial) public {
        address actor = address(0x1000);
        vm.assume(initial < type(uint256).max);
        vm.assume(amount < type(uint256).max);
        vm.assume(initial + amount < initial); // forces overflow on assignment
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: initial}();
        vm.prank(actor);
        // we need the overflow to happen at +=, so call again with amount that overflows
        c.addToBalance{value: amount}();
        uint256 bal = c.getBalance(actor);
        assertTrue(bal >= amount);
    }
}

