pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint96 smallSeed) public {
        // Restrict amount to avoid revert on legitimate overflow for the reference, but keep wide enough to catch the bug.
        // For the reference, require(((balance + amount) >= balance)) ensures no overflow, but the mutant updates first.
        // We need a value large enough that (balance + amount) wraps around in the mutant's post-update check.
        // After the mutant's update, the require uses the new balance which already overflowed, so it will not revert.
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint256).max - 1);

        // Use a fresh address to avoid state interference
        address user = address(uint160(uint256(keccak256(abi.encode(smallSeed)))));
        vm.assume(user != address(0));

        // Ensure the user has enough ether to send
        vm.deal(user, amount);

        // Record initial balance
        uint256 initialBalance = c.getBalance(user);

        // Perform the payable call
        vm.prank(user);
        try c.addToBalance{value: amount}() { }
        catch { }

        // After the call, for the reference, the balance must be initialBalance + amount exactly if no revert.
        // For the mutant, if amount is large enough, the update happens before the require, and the require still passes because it checks the already-overflowed balance.
        // This leads to a balance that is not equal to initialBalance + amount.
        uint256 finalBalance = c.getBalance(user);
        assertTrue(finalBalance == initialBalance + amount);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address u, uint amt) public payable {
        require(address(this).balance >= amt);
        c.addToBalance{value: amt}();
        c.withdrawBalance();
        assert(address(0).balance == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        c.addToBalance{value: amount}();
        uint balBefore = address(c).balance;
        bool reverted; try c.withdrawBalance() { reverted = false; } catch { reverted = true; }
        uint balAfter = address(c).balance;
        assert(!reverted ? balAfter == balBefore - amount : true);
    }
    receive() external payable {}
}

